package com.payguard.payment.service; import com.fasterxml.jackson.databind.ObjectMapper; import com.payguard.payment.domain.*; import com.payguard.payment.outbox.*; import com.payguard.payment.repository.TransactionRepository; import jakarta.transaction.Transactional; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service; @Service public class PaymentService { private final TransactionRepository tx; private final OutboxRepository outbox; private final FraudEngineClient fraud; private final ObjectMapper json; public PaymentService(TransactionRepository tx,OutboxRepository outbox,FraudEngineClient fraud,ObjectMapper json){this.tx=tx;this.outbox=outbox;this.fraud=fraud;this.json=json;} @Transactional public Transaction create(String merchant,long amount,String currency){String id=UUID.randomUUID().toString();Transaction t=tx.save(new Transaction(id,merchant,amount,currency));event(t,"payment.created",Map.of("event_id",UUID.randomUUID().toString(),"transaction_id",id,"merchant_id",merchant,"amount_minor",amount,"currency",currency,"occurred_at",Instant.now().toString()));FraudEngineClient.Decision decision=fraud.score(id,merchant,amount,currency);t.decision(decision.score(),decision.decision()); if("APPROVE".equals(decision.decision()))t.status(TransactionStatus.APPROVED); else if("REVIEW".equals(decision.decision()))t.status(TransactionStatus.HELD); else {t.status(TransactionStatus.BLOCKED);event(t,"payment.failed",Map.of("event_id",UUID.randomUUID().toString(),"transaction_id",id,"merchant_id",merchant,"occurred_at",Instant.now().toString()));} return t;} @Transactional public Transaction get(String id,String merchant){return tx.findByTransactionIdAndMerchantId(id,merchant).orElseThrow(()->new NoSuchElementException("payment not found"));} private void event(Transaction t,String type,Map<String,Object> payload){try{outbox.save(new OutboxEntry((String)payload.get("event_id"),t.getTransactionId(),type,type,t.getMerchantId(),json.writeValueAsString(payload)));}catch(Exception e){throw new IllegalStateException("cannot serialize payment event",e);}} }
